use super::*;
use crate::circuit::{Op,OperationType,analyze_ops};use crate::sim::Simulator;use sha3::digest::XofReader;
#[path="product_repair57_kernel.rs"]mod kernel;
fn prepare(){crate::point_add::clear_process_env();crate::point_add::install_skywalk_submission_recipe();std::env::set_var("EXACT_PAIR_CARRY","1");crate::point_add::leapfrog::install_recipe();}
fn mix(mut x:u64)->u64{x=(x^(x>>30)).wrapping_mul(0xbf58476d1ce4e5b9);x=(x^(x>>27)).wrapping_mul(0x94d049bb133111eb);x^(x>>31)}
struct Tape{seed:u64,at:u64}impl XofReader for Tape{fn read(&mut self,o:&mut[u8]){assert_eq!(o.len(),8);let x=match self.seed{0=>0,1=>u64::MAX,s=>mix(s^self.at)};self.at+=1;o.copy_from_slice(&x.to_le_bytes());}}
fn reference(x:u64,e:u64,n:u64,s:u64,mw:usize)->u64{let r=n+(x&7);let low=(x&63)+e+((r&1)<<4)+(((r^(r>>1))&1)<<5);let y=((s!=0)as u64)*(low>>3&1)+2*(s>>1&1)*(low>>4&1)+4*((s&1)&(s>>1&1))*(low>>5&1);let borrow=((x&7)+e>=8)as i128;let k=r as i128+8*(y as i128-borrow);((x as i128+e as i128-((1i128<<32)+976)*k)&((1i128<<mw)-1))as u64}
fn set(q:&mut[u64],ids:&[u64],x:u64){for(i,&id)in ids.iter().enumerate(){q[id as usize]=if x>>i&1!=0{u64::MAX}else{0};}}
fn word(q:&[u64],ids:&[u64])->u64{ids.iter().enumerate().fold(0,|x,(i,&id)|x|((q[id as usize]&1)<<i))}
fn hexbits(q:&mut[u64],ids:&[u64],hex:&str){assert_eq!(hex.len(),64);for (i,ch)in hex.chars().rev().enumerate(){let v=ch.to_digit(16).unwrap();for j in 0..4{q[ids[4*i+j]as usize]=if v>>j&1!=0{u64::MAX}else{0};}}}
fn kinds(ops:&[Op])->std::collections::BTreeMap<String,usize>{let mut m=std::collections::BTreeMap::new();for o in ops{*m.entry(format!("{:?}",o.kind)).or_default()+=1;}m}
fn actual(mw:usize)->(Vec<Op>,Vec<u32>,Vec<u32>){crate::point_add::pingpong::with_phase_cap(Some(1234),||{let mut c=Builder::new();let qs=c.alloc_qubits(NQ);let bs=c.alloc_bits(NB);for &i in FQ{c.release_clean(qs[i as usize]);}for &i in FB{c.free_bit(bs[i as usize]);}assert_eq!(c.op_count(),0);let entry=c.y42_alloc_state();let active=c.active_qubits();let ids=|a:&[u64]|a.iter().map(|&x|QubitId(x)).collect::<Vec<_>>();let old=PAYLOAD_AT.with(|x|x.replace(Some((false,104))));let plan=fold_fwd_v2(&mut c,&ids(&TG[..mw]),ids(E).try_into().unwrap(),ids(NM).try_into().unwrap(),QubitId(K[0]),QubitId(K[1]),0,None,false,0);PAYLOAD_AT.with(|x|x.set(old));let exit=c.y42_alloc_state();let mut eq=entry.0.clone();let mut xq=exit.0.clone();eq.sort_unstable();xq.sort_unstable();assert_eq!(eq,xq);let mut eb=entry.1.clone();let mut xb=exit.1.clone();eb.sort_unstable();xb.sort_unstable();assert_eq!(eb,xb);assert_eq!(entry.2,exit.2);assert_eq!(c.active_qubits(),active);assert_eq!(c.i13_dims(),(NQ,NB));eprintln!("REPAIR57_ACTUAL mw={mw} plan={plan:?} peak={} expected_proxy={} entryFreeQ={:?} exitFreeQ={:?} freeB_order_equal={} allsets_equal=true dims={:?}",c.peak_total(),c.expected_total(),entry.0,exit.0,entry.1==exit.1,c.i13_dims());let ops=c.take_ops();eprintln!("REPAIR57_ACTUAL_COST mw={mw} ops={} kinds={:?} score=NONE",ops.len(),kinds(&ops));(ops,exit.0,exit.1)})}
fn check(ops:&[Op],q:&[u64],b:&[u64],expected:&[u64],label:&str)->[usize;3]{let a=kernel::audit(ops,q,b).unwrap_or_else(|e|panic!("{label}: {e}"));assert_eq!(a.qubits,expected,"{label} allMR/value");let mut costs=[0;3];for(i,seed)in[0,1,0xa5a5a5a5a5a5a5a5].into_iter().enumerate(){let mut tape=Tape{seed,at:0};let mut sim=Simulator::new(q.len(),b.len(),&mut tape);sim.qubits=q.to_vec();sim.bits=b.to_vec();sim.phase=0x9c7188aafed12345;sim.apply_iter(ops.iter());assert_eq!(sim.qubits,expected,"{label}");assert_eq!(sim.phase,0x9c7188aafed12345,"{label}");for i in 0..NB.min(b.len()){if !FB.contains(&(i as u64)){assert_eq!(sim.bits[i],b[i],"live classic {i}");}}costs[i]=sim.stats.toffoli_gates as usize;}costs}
#[test]fn product_repair57_actual104(){prepare();let old=actual(56);let new=actual(57);eprintln!("REPAIR57_EXIT_ORDER oldnew_q_equal={} oldnew_b_equal={}",old.1==new.1,old.2==new.2);for(mw,ops)in[(56,&old.0),(57,&new.0)]{for dirty in[0,u64::MAX,0xa5a5a5a5a5a5a5a5]{let mut q:Vec<_>=(0..NQ).map(|i|if FQ.contains(&(i as u64)){0}else{mix(i as u64^123)}).collect();hexbits(&mut q,TG,"7a4e0d82c6cfb75c6eb7f1421011c73d8ce621ce8109201d0f000022845abac1");set(&mut q,E,3);set(&mut q,NM,4);set(&mut q,K,3);let mut want=q.clone();let x=word(&q,&TG[..mw]);set(&mut want,&TG[..mw],reference(x,3,4,3,mw));let cost=check(ops,&q,&vec![dirty;NB],&want,"actual104 point94");eprintln!("REPAIR57_POINT94 mw={mw} before={x:#x} after={:#x} executed64={cost:?} dirty={dirty:#x} allMR_phase_zero=true",word(&want,&TG[..mw]));if mw==57{let mut correct=q.clone();hexbits(&mut correct,TG,"7a4e0d82c6cfb75c6eb7f1421011c73d8ce621ce8109201d0effffed8459f0b4");assert_eq!(want,correct,"57-bit exact actual94 full logical word");}else{assert_ne!(want,q);}}
let mask=((1u64<<mw)-1)&!63;for high in[0,mask,0xaaaaaaaaaaaaaa&mask,((1u64<<32)-1)&mask]{for base in(0..1usize<<14).step_by(64){let mut q=vec![0;NQ];let mut want=q.clone();for lane in 0..64{let raw=(base+lane)as u64;let x=(raw&63)|high;for(i,&id)in TG[..mw].iter().enumerate(){q[id as usize]|=(x>>i&1)<<lane;want[id as usize]|=(reference(x,raw>>6&7,raw>>9&7,raw>>12&3,mw)>>i&1)<<lane;}for(i,&id)in E.iter().chain(NM).chain(K).enumerate(){let v=(raw>>(i+6)&1)<<lane;q[id as usize]|=v;want[id as usize]|=v;}}check(ops,&q,&vec![u64::MAX;NB],&want,"low-domain");}}}let mut fault=old.0.clone();let mut c=Builder::new();let qs=c.alloc_qubits(NQ);c.x(qs[FQ[0]as usize]);fault.extend(c.take_ops());assert_ne!(kernel::audit(&fault,&vec![0;NQ],&vec![0;NB]).unwrap().qubits,vec![0;NQ]);eprintln!("REPAIR57_TOTAL lowdomain=16384 highs=4 widths=2 fixedInputALLMR=131072 native=393216 dirtyFreeClassic=true plantedScratchFaultDetected=true score=NONE");}
#[test]fn product_repair57_body_inverse_probe(){prepare();for widths in[(56,56),(57,56),(57,57)]{crate::point_add::pingpong::with_phase_cap(Some(1234),||{let mut c=Builder::new();let abi=c.alloc_qubits(512);let _bs=c.alloc_bits(512);let source=c.alloc_qubits(256);let letter=c.alloc_qubits(5);let mut p=[abi[256..].to_vec(),source.clone()];PRODUCT_REPAIR57_WIDTH.with(|x|x.set(Some(widths)));let active=c.active_qubits();let entry=c.y42_alloc_state();fwd_tick(&mut c,104,&letter,&mut p);let forward=c.op_count();rev_tick(&mut c,104,&letter,&mut p);PRODUCT_REPAIR57_WIDTH.with(|x|x.set(None));assert_eq!(c.active_qubits(),active);let exit=c.y42_alloc_state();let (nq,nb)=c.i13_dims();let ops=c.take_ops();let mut q=vec![0;nq];let ids=|a:&[QubitId]|a.iter().map(|x|x.0).collect::<Vec<_>>();hexbits(&mut q,&ids(&abi[256..]),"71d7a5b707c0479b38f3c4aac166949b919d8a9728abbf6ba32ea98604260da0");hexbits(&mut q,&ids(&source),"f789983440f0903eca3bd368b154cd5e04b768c8a7a29f4e942ea9637fcb52db");set(&mut q,&ids(&letter),28);for i in 0..256{q[i]=mix(i as u64);}let expected=q.clone();let b=vec![u64::MAX;nb];let a=kernel::audit(&ops,&q,&b);match a{Ok(a)=>{let bad:Vec<_>=a.qubits.iter().zip(&expected).enumerate().filter(|(_, (a,b))|a!=b).map(|(i,_)|i).collect();eprintln!("REPAIR57_BODY widths={widths:?} nq={nq} nb={nb} forwardops={forward} pairOps={} kinds={:?} wrong_wires={bad:?} allMR_phase_zero=true active_restored=true entry_free={:?} exit_free={:?} score=NONE",ops.len(),kinds(&ops),entry,exit);},Err(e)=>eprintln!("REPAIR57_BODY widths={widths:?} STRICT_ALLMR_FAILURE {e} score=NONE")};for seed in[0,1,0xa5a5a5a5a5a5a5a5]{let mut tape=Tape{seed,at:0};let mut sim=Simulator::new(nq,nb,&mut tape);sim.qubits=q.clone();sim.bits=b.clone();sim.phase=0x124897da;sim.apply_iter(ops[..forward].iter());let outhex=(0..64).rev().map(|j|{let x=(0..4).fold(0,|v,k|v|((sim.qubits[abi[256+4*j+k].0 as usize]&1)<<k));format!("{x:x}")}).collect::<String>();sim.apply_iter(ops[forward..].iter());let wrong=sim.qubits.iter().zip(&expected).filter(|(a,b)|a!=b).count();let scratch=sim.qubits[773..].iter().filter(|x|**x!=0).count();eprintln!("REPAIR57_BODY_NATIVE widths={widths:?} seed={seed:#x} forwardhex={outhex} inverse_wrong={wrong} scratch_nonzero={scratch} phase_delta={:#x} executed64={}",sim.phase^0x124897da,sim.stats.toffoli_gates);}});}}
